          "starterCode": "public class MyList {\n    MyListNode head, tail;\n    int size;\n\n    MyList() {\n        head = tail = null;\n        size = 0;\n    }\n\n    boolean isEmpty() {\n        return head == null;\n    }\n\n    void clear() {\n        head = tail = null;\n        size = 0;\n    }\n\n    // Q1.1 [1 mark] addLast - if xPrice<1000 then do nothing; otherwise add\n    // a new node with type=xType, capacity=xCapacity, price=xPrice to the\n    // end of the list.\n    void addLast(String xType, int xCapacity, int xPrice) {\n        //You should write here appropriate statements to complete this function.\n\n    }\n\n    void print() {\n        MyListNode p = head;\n        while (p != null) {\n            System.out.print(p.info + \" \");\n            p = p.next;\n        }\n        System.out.println();\n    }\n\n    // Do not edit — tests addLast() above.\n    void f1() {\n        clear();\n        addLast(\"A\", 9, 1500);\n        addLast(\"D\", 3, 500);   // price<1000: must be skipped\n        addLast(\"B\", 5, 3000);\n        addLast(\"C\", 6, 5000);\n        addLast(\"E\", 7, 9000);\n        addLast(\"F\", 4, 7000);\n        print(); // -> f1.txt\n    }\n\n    // Q1.2 [1 mark] f2 - insert x, y so that y becomes the 2nd node and x\n    // becomes the last node.\n    void f2() {\n        clear();\n        addLast(\"F16\", 9, 8000);\n        addLast(\"Mic20\", 6, 3000);\n        addLast(\"SU30\", 8, 5000);\n        addLast(\"B52\", 5, 4000);\n        addLast(\"T30\", 4, 9000);\n        print(); // before\n\n        Plane x = new Plane(\"Boeing747\", 400, 1500);\n        Plane y = new Plane(\"AirbusA300\", 300, 2000);\n\n        //You should write here appropriate statements to complete this function.\n\n\n        print(); // after -> f2.txt\n    }\n\n    // Q1.3 [1 mark] f3 - swap the element at position 1 with the element at\n    // position 4 (head's position is 0). Only swap data, not nodes.\n    void f3() {\n        clear();\n        addLast(\"C\", 9, 2000);\n        addLast(\"D\", 2, 5000);\n        addLast(\"E\", 8, 7000);\n        addLast(\"F\", 1, 6000);\n        addLast(\"G\", 5, 9000);\n        addLast(\"H\", 6, 4000);\n        print(); // before\n\n        //You should write here appropriate statements to complete this function.\n\n\n        print(); // after -> f3.txt\n    }\n\n    // Q1.4 [1 mark] f4 - reverse the last 4 elements. Only swap data, not\n    // nodes.\n    void f4() {\n        clear();\n        addLast(\"C\", 7, 6000);\n        addLast(\"D\", 12, 5000);\n        addLast(\"E\", 6, 1100);\n        addLast(\"F\", 5, 4000);\n        addLast(\"I\", 4, 3000);\n        addLast(\"J\", 3, 2000);\n        addLast(\"K\", 2, 1000);\n        print(); // before\n\n        //You should write here appropriate statements to complete this function.\n\n\n        print(); // after -> f4.txt\n    }\n\n    public static void main(String[] args) {\n        MyList t = new MyList();\n        System.out.println(\"=== f1 ===\");\n        t.f1();\n        System.out.println(\"=== f2 ===\");\n        t.f2();\n        System.out.println(\"=== f3 ===\");\n        t.f3();\n        System.out.println(\"=== f4 ===\");\n        t.f4();\n    }\n}\n",
          "sampleSolution": "public class MyList {\n    MyListNode head, tail;\n    int size;\n\n    MyList() {\n        head = tail = null;\n        size = 0;\n    }\n\n    boolean isEmpty() {\n        return head == null;\n    }\n\n    void clear() {\n        head = tail = null;\n        size = 0;\n    }\n\n    // Q1.1 [1 mark] addLast - if xPrice<1000 then do nothing; otherwise add\n    // a new node with type=xType, capacity=xCapacity, price=xPrice to the\n    // end of the list.\n    void addLast(String xType, int xCapacity, int xPrice) {\n        if (xPrice < 1000) return;\n        MyListNode p = new MyListNode(new Plane(xType, xCapacity, xPrice));\n        if (isEmpty()) {\n            head = tail = p;\n        } else {\n            tail.next = p;\n            tail = p;\n        }\n        size++;\n    }\n\n    void print() {\n        MyListNode p = head;\n        while (p != null) {\n            System.out.print(p.info + \" \");\n            p = p.next;\n        }\n        System.out.println();\n    }\n\n    // Do not edit — tests addLast() above.\n    void f1() {\n        clear();\n        addLast(\"A\", 9, 1500);\n        addLast(\"D\", 3, 500);   // price<1000: must be skipped\n        addLast(\"B\", 5, 3000);\n        addLast(\"C\", 6, 5000);\n        addLast(\"E\", 7, 9000);\n        addLast(\"F\", 4, 7000);\n        print(); // -> f1.txt\n    }\n\n    // Q1.2 [1 mark] f2 - insert x, y so that y becomes the 2nd node and x\n    // becomes the last node.\n    void f2() {\n        clear();\n        addLast(\"F16\", 9, 8000);\n        addLast(\"Mic20\", 6, 3000);\n        addLast(\"SU30\", 8, 5000);\n        addLast(\"B52\", 5, 4000);\n        addLast(\"T30\", 4, 9000);\n        print(); // before\n\n        Plane x = new Plane(\"Boeing747\", 400, 1500);\n        Plane y = new Plane(\"AirbusA300\", 300, 2000);\n\n        MyListNode py = new MyListNode(y);\n        py.next = head.next;\n        head.next = py;\n        size++;\n\n        MyListNode px = new MyListNode(x);\n        tail.next = px;\n        tail = px;\n        size++;\n\n        print(); // after -> f2.txt\n    }\n\n    // Q1.3 [1 mark] f3 - swap the element at position 1 with the element at\n    // position 4 (head's position is 0). Only swap data, not nodes.\n    void f3() {\n        clear();\n        addLast(\"C\", 9, 2000);\n        addLast(\"D\", 2, 5000);\n        addLast(\"E\", 8, 7000);\n        addLast(\"F\", 1, 6000);\n        addLast(\"G\", 5, 9000);\n        addLast(\"H\", 6, 4000);\n        print(); // before\n\n        MyListNode p1 = nodeAt(1);\n        MyListNode p4 = nodeAt(4);\n        Plane tmp = p1.info;\n        p1.info = p4.info;\n        p4.info = tmp;\n\n        print(); // after -> f3.txt\n    }\n\n    // Q1.4 [1 mark] f4 - reverse the last 4 elements. Only swap data, not\n    // nodes.\n    void f4() {\n        clear();\n        addLast(\"C\", 7, 6000);\n        addLast(\"D\", 12, 5000);\n        addLast(\"E\", 6, 1100);\n        addLast(\"F\", 5, 4000);\n        addLast(\"I\", 4, 3000);\n        addLast(\"J\", 3, 2000);\n        addLast(\"K\", 2, 1000);\n        print(); // before\n\n        int lo = size - 4, hi = size - 1;\n        while (lo < hi) {\n            MyListNode a = nodeAt(lo);\n            MyListNode b = nodeAt(hi);\n            Plane tmp = a.info;\n            a.info = b.info;\n            b.info = tmp;\n            lo++;\n            hi--;\n        }\n\n        print(); // after -> f4.txt\n    }\n\n    private MyListNode nodeAt(int pos) {\n        MyListNode p = head;\n        for (int i = 0; i < pos; i++) p = p.next;\n        return p;\n    }\n\n    public static void main(String[] args) {\n        MyList t = new MyList();\n        System.out.println(\"=== f1 ===\");\n        t.f1();\n        System.out.println(\"=== f2 ===\");\n        t.f2();\n        System.out.println(\"=== f3 ===\");\n        t.f3();\n        System.out.println(\"=== f4 ===\");\n        t.f4();\n    }\n}\n",
