          "sampleSolution": "import java.util.LinkedList;\nimport java.util.Queue;\n\npublic class BSTree {\n    BSTNode root;\n\n    BSTree() {\n        root = null;\n    }\n\n    void clear() {\n        root = null;\n    }\n\n    // Q2.1 [1 mark] insert - insert a new User with name=xName, age=xAge,\n    // id=xId into the tree (id is the key, must be unique; age>0).\n    void insert(String xName, int xAge, int xId) {\n        if (xAge <= 0) return;\n        BSTNode p = new BSTNode(new User(xName, xAge, xId));\n        if (root == null) { root = p; return; }\n        BSTNode cur = root, parent = null;\n        while (cur != null) {\n            if (cur.info.id == xId) return; // unique key, reject duplicate\n            parent = cur;\n            if (xId < cur.info.id) cur = cur.left;\n            else cur = cur.right;\n        }\n        if (xId < parent.info.id) parent.left = p;\n        else parent.right = p;\n    }\n\n    private void loadBase() {\n        clear();\n        insert(\"A\", 50, 8);\n        insert(\"B\", 10, 2);\n        insert(\"E\", 30, 10);\n        insert(\"C\", 4, 5);\n        insert(\"F\", 14, 9);\n        insert(\"H\", 34, 11);\n        insert(\"D\", 25, 4);\n        insert(\"G\", 7, 6);\n        insert(\"J\", 19, 3);\n        insert(\"I\", 20, 7);\n    }\n\n    void breadth(BSTNode p) {\n        if (p == null) return;\n        Queue<BSTNode> q = new LinkedList<>();\n        q.add(p);\n        while (!q.isEmpty()) {\n            BSTNode r = q.poll();\n            System.out.print(r.info + \" \");\n            if (r.left != null) q.add(r.left);\n            if (r.right != null) q.add(r.right);\n        }\n        System.out.println();\n    }\n\n    void preOrder(BSTNode p) {\n        if (p == null) return;\n        System.out.print(p.info + \" \");\n        preOrder(p.left);\n        preOrder(p.right);\n    }\n\n    void preOrderRoot() {\n        preOrder(root);\n        System.out.println();\n    }\n\n    void inOrder(BSTNode p) {\n        if (p == null) return;\n        inOrder(p.left);\n        System.out.print(p.info + \" \");\n        inOrder(p.right);\n    }\n\n    void inOrderRoot() {\n        inOrder(root);\n        System.out.println();\n    }\n\n    void postOrder(BSTNode p) {\n        if (p == null) return;\n        postOrder(p.left);\n        postOrder(p.right);\n        System.out.print(p.info + \" \");\n    }\n\n    // Do not edit — tests insert() above.\n    void f1() {\n        loadBase();\n        breadth(root);\n        inOrderRoot();\n    }\n\n    // Q2.2 [1 mark] f2 - perform the post-order traversal from the root but\n    // write only the nodes with age<25. (Hint: copy postOrder(...) to\n    // postOrder2(...) and modify it.)\n    void f2() {\n        loadBase();\n        preOrderRoot(); // given, unedited \"before\" check\n        postOrder2(root);\n        System.out.println();\n    }\n\n    private void postOrder2(BSTNode p) {\n        if (p == null) return;\n        postOrder2(p.left);\n        postOrder2(p.right);\n        if (p.info.age < 25) System.out.print(p.info + \" \");\n    }\n\n    // Q2.3 [1 mark] f3 - add 3 to the age of all nodes that have only one\n    // child (age=age+3).\n    void f3() {\n        loadBase();\n        breadth(root); // given, unedited \"before\" check\n        addThreeToSingleChildNodes(root);\n        breadth(root);\n    }\n\n    private void addThreeToSingleChildNodes(BSTNode p) {\n        if (p == null) return;\n        boolean hasLeft = p.left != null;\n        boolean hasRight = p.right != null;\n        if (hasLeft != hasRight) p.info.age += 3;\n        addThreeToSingleChildNodes(p.left);\n        addThreeToSingleChildNodes(p.right);\n    }\n\n    // Q2.4 [1 mark] f4 - calculate the height of the last node in the\n    // postOrder traversal from the root (height of a single node = 1).\n    int f4() {\n        loadBase();\n        preOrderRoot(); // given, unedited \"before\" check\n        return height(root);\n    }\n\n    private int height(BSTNode p) {\n        if (p == null) return 0;\n        return 1 + Math.max(height(p.left), height(p.right));\n    }\n\n    // Q2.5 [1 mark] f5 - set the age of all nodes located in the left branch\n    // of the 1st node in the preOrder traversal from the root to zero.\n    void f5() {\n        loadBase();\n        inOrderRoot(); // given, unedited \"before\" check\n        setZeroRec(root.left); // 1st preOrder node is root itself; its left branch\n        inOrderRoot();\n    }\n\n    private void setZeroRec(BSTNode p) {\n        if (p == null) return;\n        p.info.age = 0;\n        setZeroRec(p.left);\n        setZeroRec(p.right);\n    }\n\n    // Q2.6 [1 mark] f6 - find the node with the biggest id (right-most node).\n    User f6() {\n        loadBase();\n        inOrderRoot(); // given, unedited \"before\" check\n        BSTNode p = root;\n        while (p.right != null) p = p.right;\n        return p.info;\n    }\n\n    public static void main(String[] args) {\n        BSTree t = new BSTree();\n        System.out.println(\"=== f1 ===\");\n        t.f1();\n        System.out.println(\"=== f2 ===\");\n        t.f2();\n        System.out.println(\"=== f3 ===\");\n        t.f3();\n        System.out.println(\"=== f4 ===\");\n        System.out.println(t.f4());\n        System.out.println(\"=== f5 ===\");\n        t.f5();\n        System.out.println(\"=== f6 ===\");\n        System.out.println(t.f6());\n    }\n}\n",
